def quadrant_kaleidoscope(grid):
    "The 2n x 2n grid whose quadrants are the grid, the flipped transpose (both ways), and the 180-degree rotation."
    t = transpose(grid)
    top = vstack(grid, t)
    return vstack(top, rot180(top))

def downscale_block(grid, block=3, bg=(0, 5)):
    "Each block x block cell replaced by the block's single non-background color, else 0 (majority-color downscale)."
    H, W = len(grid), len(grid[0])
    out = []
    for br in range(0, H, block):
        row = []
        for bc in range(0, W, block):
            cnt = Counter()
            for i in range(br, min(br + block, H)):
                for j in range(bc, min(bc + block, W)):
                    if grid[i][j] not in bg:
                        cnt[grid[i][j]] += 1
            row.append(cnt.most_common(1)[0][0] if cnt else 0)
        out.append(row)
    return out

def overlap_half(grid, color=2):
    "Split the grid at the solid separator line that leaves two equal halves; cells nonzero in both halves become color."
    H, W = len(grid), len(grid[0])
    sep = None
    for i in range(H):
        if all(v == grid[i][0] for v in grid[i]) and H % 2 == 0 and i == H // 2 - 1:
            pass
    for i in range(1, H - 1):
        if all(v != 0 for v in grid[i]) and (H - 1 - i) == i:
            sep = i
    out = [row[:] for row in grid]
    if sep is not None:
        top, bot = grid[:sep], grid[sep + 1:]
        out = [[color if a != 0 and b != 0 else (a or b) for a, b in zip(ra, rb)]
               for ra, rb in zip(top, bot[::-1])]
    return out

def fill_between_markers(grid, fill=3):
    "Cells strictly between consecutive non-background (marker) cells in each row and column become fill; other cells unchanged."
    bg = background(grid)
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    for i in range(H):
        cols = [j for j in range(W) if grid[i][j] != bg]
        for a, b in zip(cols, cols[1:]):
            for j in range(a + 1, b):
                out[i][j] = fill
    for j in range(W):
        rows = [i for i in range(H) if grid[i][j] != bg]
        for a, b in zip(rows, rows[1:]):
            for i in range(a + 1, b):
                out[i][j] = fill
    return out

